#include <bits/stdc++.h>
using namespace std;

optional<vector<int>> two_color(const vector<vector<int>>& adj) {
    int cnt = static_cast<int>(adj.size()) - 1;
    vector<int> color(cnt + 1);
    queue<int> pending;

for (int start = 1; start <= cnt; ++start) {
    if (color[start] != 0) {
        continue;
    }
    color[start] = 1;
    pending.push(start);
    while (!pending.empty()) {
        int vertex = pending.front();
        pending.pop();
        for (int next : adj[vertex]) {
            if (color[next] == 0) {
                color[next] = 3 - color[vertex];
                pending.push(next);
            } else if (color[next] == color[vertex]) {
                return nullopt;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n + 1);
    for (int edge = 0; edge < m; ++edge) {
        int first, second;
        cin >> first >> second;
        adj[first].push_back(second);
        adj[second].push_back(first);
    }
    auto color = two_color(adj);
    if (!color.has_value()) {
        cout << "IMPOSSIBLE\n";
        return 0;
    }
    for (int vertex = 1; vertex <= n; ++vertex) {
        cout << (*color)[vertex] << (vertex == n ? '\n' : ' ');
    }
}

